package com.psgill.puppy;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Exercises the overlay's paint path against an offscreen image, since the
 * real one only runs inside a logged-in client.
 */
public class PuppyOverlayTest
{
	private static final long MINUTE = 60_000L;

	/** All-defaults config; individual tests override single methods. */
	private static class TestConfig implements PuppyConfig
	{
	}

	private static PuppyOverlay overlayWith(PuppyConfig config)
	{
		// The plugin reference is only touched by render(), not drawCard().
		return new PuppyOverlay(null, config);
	}

	private static Graphics2D graphics()
	{
		return new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	/** Five minutes grown, five minutes since a feed. */
	private static PuppyTracker growing()
	{
		return at(5, 5);
	}

	/** A tracker reading the two counters the game would be holding. */
	private static PuppyTracker at(int growthMinutes, int fedMinutes)
	{
		PuppyTracker tracker = new PuppyTracker();
		tracker.setFollowing(true, "Rover");
		tracker.update(growthMinutes, fedMinutes, 5 * MINUTE);
		return tracker;
	}

	@Test
	public void drawsACardOfAReasonableSize()
	{
		Dimension size = overlayWith(new TestConfig()).drawCard(graphics(), growing(), 5 * MINUTE);

		assertNotNull(size);
		assertEquals(168, size.width);
		assertTrue(size.height > 40);
		assertTrue(size.height < 140);
	}

	@Test
	public void aGrownDogLosesTheGrowthRowsAndShrinks()
	{
		PuppyTracker grown = at(PuppyTracker.GROWN_MINUTES, 5);

		int growingHeight = overlayWith(new TestConfig()).drawCard(graphics(), growing(), 5 * MINUTE).height;
		int grownHeight = overlayWith(new TestConfig()).drawCard(graphics(), grown, 5 * MINUTE).height;

		assertTrue(grownHeight < growingHeight);
	}

	// ------------------------------------------------------------- minimise

	@Test
	public void minimisingShrinksTheCard()
	{
		PuppyOverlay overlay = overlayWith(new TestConfig());
		int full = overlay.drawCard(graphics(), growing(), 5 * MINUTE).height;

		overlay.setMinimised(true);
		Dimension small = overlay.drawCard(graphics(), growing(), 5 * MINUTE);

		assertTrue(small.height < full);
		assertTrue(small.width < 168);
	}

	@Test
	public void clickingTheButtonTogglesAndSwallowsTheClick()
	{
		PuppyOverlay overlay = overlayWith(new TestConfig());
		overlay.drawCard(graphics(), growing(), 5 * MINUTE);

		// The button is drawn at the top right of the card; the overlay has
		// not been laid out by a client, so its origin is 0,0.
		Point onButton = new Point(168 - 9 - 6, 9 + 14 - 6);

		assertTrue(overlay.handleClick(onButton));
		assertTrue(overlay.isMinimised());

		// Repainting collapsed moves the button, so find it again.
		overlay.drawCard(graphics(), growing(), 5 * MINUTE);
		assertTrue(overlay.handleClick(new Point(112 - 9 - 6, 9 + 14 - 7)));
		assertFalse(overlay.isMinimised());
	}

	@Test
	public void clicksElsewhereArePassedThrough()
	{
		PuppyOverlay overlay = overlayWith(new TestConfig());
		overlay.drawCard(graphics(), growing(), 5 * MINUTE);

		assertFalse(overlay.handleClick(new Point(20, 60)));
		assertFalse(overlay.handleClick(new Point(400, 400)));
		assertFalse(overlay.isMinimised());
	}

	@Test
	public void aClickBeforeAnythingIsPaintedIsIgnored()
	{
		assertFalse(overlayWith(new TestConfig()).handleClick(new Point(5, 5)));
	}

	@Test
	public void theCollapsedCardStillShowsTheGrowthTime()
	{
		PuppyOverlay overlay = overlayWith(new TestConfig());
		overlay.setMinimised(true);

		assertNotNull(overlay.drawCard(graphics(), growing(), 5 * MINUTE));

		assertNotNull(overlay.drawCard(graphics(),
			at(PuppyTracker.GROWN_MINUTES, 5), 5 * MINUTE));
	}

	@Test
	public void aStoppedPuppyStillPaints()
	{
		PuppyTracker tracker = at(20, PuppyTracker.FEED_MINUTES);

		Dimension size = overlayWith(new TestConfig()).drawCard(graphics(), tracker, 40 * MINUTE);

		assertNotNull(size);
		assertTrue(tracker.isGrowthPaused());
		assertTrue(size.height > 0);
	}

	@Test
	public void aPuppyWithNoReadingYetStillPaints()
	{
		PuppyTracker fresh = new PuppyTracker();
		fresh.setFollowing(true, "Rover");

		assertNotNull(overlayWith(new TestConfig()).drawCard(graphics(), fresh, 0));
	}
}

package com.psgill.puppy;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a full RuneLite client with this plugin already loaded and
 * enabled — RuneLite's own standard way of running a plugin under
 * development, no sideloading tool needed. Uses your existing profile and
 * login from ~/.runelite, same as the normal client.
 *
 * Run it with {@code ./gradlew runPlugin}, or right-click > Run in IntelliJ.
 *
 * Holds no {@code @Test} methods, so Gradle's test task ignores it.
 */
public class PuppyPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PuppyPlugin.class);
		RuneLite.main(args);
	}
}

package com.psgill.puppy;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class PuppyFormatTest
{
	@Test
	public void showsSecondsUnderAMinute()
	{
		assertEquals("45s", PuppyFormat.duration(45_000));
		assertEquals("0s", PuppyFormat.duration(0));
	}

	@Test
	public void showsMinutesAndSecondsUnderAnHour()
	{
		assertEquals("12m 30s", PuppyFormat.duration(750_000));
		assertEquals("1m 00s", PuppyFormat.duration(60_000));
	}

	@Test
	public void dropsSecondsAboveAnHour()
	{
		assertEquals("1h 05m", PuppyFormat.duration(3_900_000));
	}

	@Test
	public void negativeDurationsClampRatherThanPrintingRubbish()
	{
		assertEquals("0s", PuppyFormat.duration(-5_000));
	}

	@Test
	public void remainingMarksOverdueWithASign()
	{
		assertEquals("2m 00s", PuppyFormat.remaining(120_000L));
		assertEquals("-2m 00s", PuppyFormat.remaining(-120_000L));
		assertEquals("--", PuppyFormat.remaining(null));
	}

	@Test
	public void remainingLongReadsAsWords()
	{
		assertEquals("in 2m 00s", PuppyFormat.remainingLong(120_000L));
		assertEquals("2m 00s overdue", PuppyFormat.remainingLong(-120_000L));
		assertEquals("not tracked yet", PuppyFormat.remainingLong(null));
	}

	@Test
	public void periodDropsEmptyTrailingUnits()
	{
		assertEquals("15m", PuppyFormat.period(900));
		assertEquals("1h", PuppyFormat.period(3600));
		assertEquals("1h 30m", PuppyFormat.period(5400));
		assertEquals("1m 30s", PuppyFormat.period(90));
	}
}

package com.psgill.puppy;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The tracker now reads the game's counters instead of estimating, so what
 * is worth testing has changed with it: not whether growth accrues at the
 * right rate, but whether the thresholds sit where the game puts them and
 * whether the seconds interpolated between two whole-minute readings stay
 * inside the minute they are filling.
 *
 * The readings used here are Infinitay's, logged from a real puppy on
 * issue #3, so the numbers below are the game's own rather than mine.
 */
public class PuppyTrackerTest
{
	private static final long MINUTE = 60_000L;

	private PuppyTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new PuppyTracker();
		tracker.setFollowing(true, "Rover");
	}

	@Test
	public void theWikisNumbersAreTheOnesUsed()
	{
		assertEquals("three hours of active growth", 3 * 60, PuppyTracker.GROWN_MINUTES);
		assertEquals("growth stops 30 minutes after a feed", 30, PuppyTracker.FEED_MINUTES);
		assertEquals("hunger warning at 15 minutes", 15, PuppyTracker.HUNGER_WARNING_MINUTES);
		assertEquals("second warning at 25 minutes", 25, PuppyTracker.VERY_HUNGRY_WARNING_MINUTES);
	}

	@Test
	public void saysNothingBeforeItHasRead()
	{
		assertFalse(tracker.hasReading());
		assertFalse("an unread puppy is not a grown one", tracker.isFullyGrown());
		assertFalse(tracker.isHungry());
		assertFalse(tracker.isGrowthPaused());
		assertNull(tracker.untilPauseMillis(0));
		assertEquals(3 * 60 * MINUTE, tracker.untilGrownMillis(0));
	}

	/** The thresholds, checked against the messages logged beside them. */
	@Test
	public void theWarningsFallWhereTheGamesDo()
	{
		tracker.update(19, 14, 0);
		assertFalse(tracker.isHungry());

		// "Your puppy is getting quite hungry."
		tracker.update(19, 15, MINUTE);
		assertTrue(tracker.isHungry());
		assertFalse(tracker.isVeryHungry());

		// "Your puppy is very hungry."
		tracker.update(29, 25, 2 * MINUTE);
		assertTrue(tracker.isVeryHungry());
		assertFalse("the game has not said it stopped yet", tracker.isGrowthPaused());

		// "Your puppy has stopped growing. You'll need to feed it..."
		tracker.update(34, 30, 3 * MINUTE);
		assertTrue(tracker.isGrowthPaused());
	}

	@Test
	public void grownIsThreeHoursOfTheGamesOwnCounting()
	{
		tracker.update(179, 5, 0);
		assertFalse(tracker.isFullyGrown());

		tracker.update(180, 5, MINUTE);
		assertTrue(tracker.isFullyGrown());
		assertEquals(0, tracker.untilGrownMillis(MINUTE));
		assertEquals(1.0, tracker.growthFraction(MINUTE), 0.0001);
	}

	@Test
	public void feedingResetsTheFedCounterAndTheCountdowns()
	{
		tracker.update(34, 30, 0);
		assertTrue(tracker.isGrowthPaused());
		assertNull("no countdown once it has already stopped", tracker.untilPauseMillis(0));

		// Immediately after feeding: FED_TIMER 30 -> 0.
		tracker.update(34, 0, MINUTE);
		assertFalse(tracker.isGrowthPaused());
		assertFalse(tracker.isHungry());
		assertEquals(30 * MINUTE, (long) tracker.untilPauseMillis(MINUTE));
		assertEquals(15 * MINUTE, (long) tracker.untilHungryMillis(MINUTE));
		assertEquals(25 * MINUTE, (long) tracker.untilVeryHungryMillis(MINUTE));
	}

	// ------------------------------------------------------- interpolation

	@Test
	public void secondsAreFilledInBetweenWholeMinuteReadings()
	{
		tracker.update(100, 10, 0);
		assertEquals(80 * MINUTE, tracker.untilGrownMillis(0));

		// Half a minute later, with the counter unchanged.
		tracker.update(100, 10, 30_000);
		assertEquals(80 * MINUTE - 30_000, tracker.untilGrownMillis(30_000));
		assertEquals(20 * MINUTE - 30_000, (long) tracker.untilPauseMillis(30_000));
	}

	/**
	 * A client that stops ticking must not let the interpolation run on.
	 *
	 * Without the clamp a stalled or backgrounded client would keep
	 * subtracting real time from a counter that had stopped being read, and
	 * walk a countdown down to zero on its own — announcing a grown puppy
	 * the game knows nothing about, which is the shape of the bug iRoxor
	 * reported against the old estimator.
	 */
	@Test
	public void interpolationNeverOutrunsItsOwnMinute()
	{
		tracker.update(179, 10, 0);

		long anHourLater = 60 * MINUTE;
		assertEquals("at most the one minute may be filled in",
			0, tracker.untilGrownMillis(anHourLater));
		assertFalse("but the reading itself still says not grown",
			tracker.isFullyGrown());
	}

	@Test
	public void aChangedReadingStartsAFreshMinute()
	{
		tracker.update(100, 10, 0);
		tracker.update(100, 10, 45_000);
		assertEquals(80 * MINUTE - 45_000, tracker.untilGrownMillis(45_000));

		// The counter ticks over: the interpolation restarts from here.
		tracker.update(101, 11, 60_000);
		assertEquals(79 * MINUTE, tracker.untilGrownMillis(60_000));
	}

	// ------------------------------------------------------------- clearing

	@Test
	public void clearingForgetsTheReadingButNotTheName()
	{
		tracker.update(180, 0, 0);
		assertTrue(tracker.isFullyGrown());

		tracker.clearReading();

		assertFalse(tracker.hasReading());
		assertFalse("a stale reading must not describe an empty heel",
			tracker.isFullyGrown());
		assertEquals("Rover", tracker.petName());
	}

	@Test
	public void anUnnamedPetIsStillCalledSomething()
	{
		assertNotNull(new PuppyTracker().petName());
		assertEquals("Puppy", new PuppyTracker().petName());
	}

	// ------------------------------------------------------- puppy or dog

	/**
	 * The rename is the only thing separating a puppy from a grown dog.
	 *
	 * Missing it is what put a fresh three hour card on screen next to a
	 * fully grown dog: the counter resets the moment one matures, so the
	 * zero that follows reads exactly like a brand new puppy.
	 */
	@Test
	public void aPuppyIsToldFromADogByItsName()
	{
		assertTrue(PuppyPlugin.isPuppyName("Pug puppy"));
		assertTrue(PuppyPlugin.isPuppyName("Greyhound puppy"));
		assertTrue("the quest's own, before a breed is known",
			PuppyPlugin.isPuppyName("Puppy"));
		assertTrue("case and stray spacing must not matter",
			PuppyPlugin.isPuppyName("  SHEEPDOG PUPPY  "));

		assertFalse("the grown dog it becomes", PuppyPlugin.isPuppyName("Pug"));
		assertFalse(PuppyPlugin.isPuppyName("Greyhound"));
		assertFalse("a cat is not a puppy", PuppyPlugin.isPuppyName("Kitten"));
		assertFalse(PuppyPlugin.isPuppyName(null));
		assertFalse(PuppyPlugin.isPuppyName(""));
	}

	@Test
	public void growthFractionTracksTheCounter()
	{
		tracker.update(90, 5, 0);
		assertEquals(0.5, tracker.growthFraction(0), 0.0001);

		tracker.update(0, 5, MINUTE);
		assertEquals(0.0, tracker.growthFraction(MINUTE), 0.0001);
	}
}

package com.psgill.puppy;

/**
 * A puppy's two clocks, read from the game rather than estimated.
 *
 * The server keeps both. {@code PUPPY_GROWTH_TRACKER} counts the minutes a
 * puppy has actually spent growing and {@code PUPPY_FED_TIMER} the minutes
 * since it was last fed; RuneLite exposed them as gamevals in 1.12.39.
 * Reading them replaced the estimator this class used to be — millisecond
 * accrual, a gap guard for logouts, "Guess age" parsing, and watching for
 * the feed click — every piece of which was an approximation of a number
 * the server already had, and every one of which drifted.
 *
 * Growth minutes are *active* minutes: the counter freezes while the puppy
 * goes unfed and resumes on feeding, and both counters freeze while logged
 * out. So there is nothing left here to compensate for.
 *
 * What the varbits do not carry is seconds. They step a minute at a time, so
 * a countdown built straight from them would sit still and then jump by a
 * minute. The wall-clock instant of each observed change is kept as an
 * anchor and the seconds since are added on top, which stays honest so long
 * as that interpolation is never allowed to run past the minute it fills.
 *
 * Holds no RuneLite types, so the whole thing can be tested by handing it
 * two numbers and a timestamp.
 */
class PuppyTracker
{
	/** Active growth minutes needed to become a dog: three hours. */
	static final int GROWN_MINUTES = 3 * 60;

	/** Growth stops this many minutes after the last feed. */
	static final int FEED_MINUTES = 30;

	/** The game's first hunger warning, "getting quite hungry". */
	static final int HUNGER_WARNING_MINUTES = 15;

	/** The game's second and more urgent one, "very hungry". */
	static final int VERY_HUNGRY_WARNING_MINUTES = 25;

	private static final long MINUTE_MILLIS = 60_000L;

	/** Last values read from the game, or null before the first read. */
	private Integer growthMinutes;

	private Integer fedMinutes;

	/**
	 * When a counter was last seen to change, which starts a fresh minute.
	 *
	 * Null until a change has actually been observed — on login the current
	 * minute is already part-spent and there is no way to know how far, so
	 * until then the interpolation contributes nothing and every countdown
	 * reads a whole minute long. That is the reading which is late rather
	 * than early, and late is the side to be wrong on: it never announces a
	 * puppy grown before the game agrees.
	 */
	private Long minuteAnchorMillis;

	private boolean following;

	private String petName;

	// ----------------------------------------------------------------- input

	/**
	 * Takes the two varbit values as they currently read.
	 *
	 * Called every tick rather than from {@code VarbitChanged}, which does
	 * not fire for a value of zero — a puppy just fed reads zero, and so
	 * does a brand new one, so an event-driven version would go blind at
	 * exactly the two moments the counters matter most.
	 */
	void update(int growth, int fed, long nowMillis)
	{
		boolean changed = growthMinutes == null
			|| fedMinutes == null
			|| growth != growthMinutes
			|| fed != fedMinutes;

		growthMinutes = growth;
		fedMinutes = fed;

		if (changed)
		{
			minuteAnchorMillis = nowMillis;
		}
	}

	/** True once the game's counters have been read at least once. */
	boolean hasReading()
	{
		return growthMinutes != null && fedMinutes != null;
	}

	// ---------------------------------------------------------------- states

	boolean isFullyGrown()
	{
		return hasReading() && growthMinutes >= GROWN_MINUTES;
	}

	/** True once the puppy has gone thirty minutes without food. */
	boolean isGrowthPaused()
	{
		return hasReading() && fedMinutes >= FEED_MINUTES;
	}

	/** True once the game's first warning is due, at fifteen minutes. */
	boolean isHungry()
	{
		return hasReading() && fedMinutes >= HUNGER_WARNING_MINUTES;
	}

	/** True once the game's second warning is due, at twenty-five. */
	boolean isVeryHungry()
	{
		return hasReading() && fedMinutes >= VERY_HUNGRY_WARNING_MINUTES;
	}

	// ------------------------------------------------------------- countdowns

	/**
	 * How far into the current minute we are, in milliseconds.
	 *
	 * Clamped to a minute so a stalled client — no ticks, so no observed
	 * change — cannot let the interpolation eat into the next minute and
	 * run a countdown to zero on its own.
	 */
	private long intoMinute(long nowMillis)
	{
		if (minuteAnchorMillis == null)
		{
			return 0;
		}

		return Math.max(0, Math.min(MINUTE_MILLIS, nowMillis - minuteAnchorMillis));
	}

	/** Milliseconds of active growth still to go; 0 once grown. */
	long untilGrownMillis(long nowMillis)
	{
		if (!hasReading())
		{
			return GROWN_MINUTES * MINUTE_MILLIS;
		}

		long whole = (long) Math.max(0, GROWN_MINUTES - growthMinutes) * MINUTE_MILLIS;
		return Math.max(0, whole - intoMinute(nowMillis));
	}

	/** Milliseconds until growth pauses, or null when it already has. */
	Long untilPauseMillis(long nowMillis)
	{
		return countdownTo(FEED_MINUTES, nowMillis);
	}

	/** Milliseconds until the first hunger warning, or null once due. */
	Long untilHungryMillis(long nowMillis)
	{
		return countdownTo(HUNGER_WARNING_MINUTES, nowMillis);
	}

	/** Milliseconds until the second hunger warning, or null once due. */
	Long untilVeryHungryMillis(long nowMillis)
	{
		return countdownTo(VERY_HUNGRY_WARNING_MINUTES, nowMillis);
	}

	private Long countdownTo(int minuteMark, long nowMillis)
	{
		if (!hasReading() || fedMinutes >= minuteMark)
		{
			return null;
		}

		long remaining = (long) (minuteMark - fedMinutes) * MINUTE_MILLIS - intoMinute(nowMillis);
		return remaining <= 0 ? null : remaining;
	}

	/** 0 to 1 across the three hours. */
	double growthFraction(long nowMillis)
	{
		if (!hasReading())
		{
			return 0;
		}

		double done = growthMinutes * MINUTE_MILLIS + intoMinute(nowMillis);
		return Math.max(0, Math.min(1, done / (GROWN_MINUTES * (double) MINUTE_MILLIS)));
	}

	// --------------------------------------------------------------- readings

	/** Active growth so far, in minutes, as the game counts it. */
	int grownMinutes()
	{
		return growthMinutes == null ? 0 : growthMinutes;
	}

	/** Minutes since the last feed, as the game counts them. */
	int fedMinutes()
	{
		return fedMinutes == null ? 0 : fedMinutes;
	}

	boolean isFollowing()
	{
		return following;
	}

	String petName()
	{
		return petName == null ? "Puppy" : petName;
	}

	// ----------------------------------------------------------------- events

	void setFollowing(boolean following, String petName)
	{
		this.following = following;

		if (petName != null && !petName.isEmpty())
		{
			this.petName = petName;
		}
	}

	/**
	 * Forgets the readings, without forgetting the pet's name.
	 *
	 * Used when there is no longer a puppy to read for. The counters are a
	 * player variable rather than a property of whatever is at your heel, so
	 * a stale pair left lying around would happily describe an adult dog, or
	 * a puppy sitting in the bank, as though it were growing.
	 */
	void clearReading()
	{
		growthMinutes = null;
		fedMinutes = null;
		minuteAnchorMillis = null;
	}
}

package com.psgill.puppy;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Two lines and a bar: how long until it needs feeding, and how long until
 * it is a dog.
 *
 * Painted by hand rather than stacked out of RuneLite's Title/Line
 * components, matching the sibling death-cost plugin — the growth bar and
 * the colour change on the feed row are the two things worth having, and
 * neither is something the stock rows do.
 */
class PuppyOverlay extends Overlay
{
	private static final int WIDTH = 168;
	private static final int MINIMISED_WIDTH = 112;
	private static final int BUTTON = 13;
	private static final int PAD = 9;
	private static final int TITLE_H = 14;
	private static final int ROW_H = 16;
	private static final int BAR_H = 5;
	private static final int BAR_GAP = 6;
	private static final int CORNER = 10;
	private static final int STRIPE_W = 3;

	// Alpha kept low enough to read the game through the card. The text and
	// the accent stripe stay fully opaque — it is the panel behind them that
	// gives way, so legibility does not pay for the transparency.
	private static final Color BACKGROUND = new Color(24, 24, 24, 140);
	private static final Color LABEL = new Color(176, 174, 163);
	private static final Color VALUE = new Color(238, 238, 238);
	private static final Color BAR_TRACK = new Color(255, 255, 255, 45);

	private static final Color OK = new Color(0x8B, 0xC3, 0x4A);
	private static final Color WARN = new Color(0xFF, 0x98, 0x1F);
	private static final Color STOPPED = new Color(0xE2, 0x4B, 0x4A);

	private static final Font TITLE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);
	private static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	private static final Font VALUE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);

	private final PuppyPlugin plugin;
	private final PuppyConfig config;

	/**
	 * Where the minimise button was last drawn, relative to the card.
	 *
	 * Kept from the paint rather than computed again at click time, because
	 * the card changes height with what it is showing and two pieces of
	 * geometry that have to agree are one more thing to get out of step.
	 */
	private final Rectangle buttonBounds = new Rectangle();

	private boolean minimised;

	@Inject
	PuppyOverlay(PuppyPlugin plugin, PuppyConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	boolean isMinimised()
	{
		return minimised;
	}

	void setMinimised(boolean minimised)
	{
		this.minimised = minimised;
	}

	/**
	 * Handles a click at a canvas point, returning true when it was ours.
	 *
	 * {@link #getBounds} is where RuneLite last laid the overlay out, so the
	 * button's screen position is that plus where it was painted inside the
	 * card. Returning true tells the plugin to swallow the click, so
	 * minimising the overlay does not also walk your character there.
	 */
	boolean handleClick(Point canvasPoint)
	{
		// The plugin check is skipped when there is no plugin, which is how
		// the paint tests drive this.
		if (buttonBounds.isEmpty() || (plugin != null && !plugin.shouldRender()))
		{
			return false;
		}

		Rectangle overlayBounds = getBounds();
		Rectangle button = new Rectangle(
			overlayBounds.x + buttonBounds.x,
			overlayBounds.y + buttonBounds.y,
			buttonBounds.width,
			buttonBounds.height);

		if (!button.contains(canvasPoint))
		{
			return false;
		}

		minimised = !minimised;
		return true;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.shouldRender())
		{
			return null;
		}

		return drawCard(g, plugin.tracker(), System.currentTimeMillis());
	}

	/**
	 * Paints the card and returns its size. Split out from {@link #render},
	 * which only runs inside a live client, so the paint path can be
	 * exercised against an offscreen image in a test.
	 */
	Dimension drawCard(Graphics2D g, PuppyTracker tracker, long now)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		boolean paused = tracker.isGrowthPaused();
		boolean grown = tracker.isFullyGrown();

		if (minimised)
		{
			return drawMinimised(g, tracker, now, grown, paused);
		}

		int rows = grown ? 0 : 2;
		int height = PAD + TITLE_H + (grown ? 0 : BAR_GAP + BAR_H) + rows * ROW_H + PAD;

		Color accent = grown ? OK : paused ? STOPPED : tracker.isHungry() ? WARN : OK;

		g.setColor(BACKGROUND);
		g.fill(new RoundRectangle2D.Float(0, 0, WIDTH, height, CORNER, CORNER));
		g.setColor(accent);
		g.fill(new RoundRectangle2D.Float(0, 0, STRIPE_W + CORNER, height, CORNER, CORNER));
		g.setColor(BACKGROUND);
		g.fillRect(STRIPE_W, 0, CORNER, height);

		int left = PAD;
		int right = WIDTH - PAD;
		int y = PAD + TITLE_H - 3;

		g.setFont(TITLE_FONT);
		g.setColor(VALUE);
		g.drawString(grown ? tracker.petName() + " (grown)" : tracker.petName(), left, y);

		drawButton(g, right, y, "-");

		if (!grown)
		{
			y += BAR_GAP;
			g.setColor(BAR_TRACK);
			g.fillRect(left, y, right - left, BAR_H);
			g.setColor(paused ? STOPPED : OK);
			g.fillRect(left, y, (int) ((right - left) * tracker.growthFraction(now)), BAR_H);
			y += BAR_H;

			y += ROW_H;
			// Without a reading there is no honest number to print: three
			// hours would be a guess dressed up as a countdown.
			row(g, "Grows in",
				tracker.hasReading() ? PuppyFormat.duration(tracker.untilGrownMillis(now)) : "-",
				VALUE, left, right, y);

			y += ROW_H;
			Long untilPause = tracker.untilPauseMillis(now);
			if (paused)
			{
				row(g, "Feed", "stopped growing", STOPPED, left, right, y);
			}
			else if (untilPause == null)
			{
				// Nothing read yet — before the first tick after login, or
				// with no pet out. Saying so is better than drawing a
				// countdown that would have to be invented.
				row(g, "Feed", "-", VALUE, left, right, y);
			}
			else
			{
				Long untilHungry = tracker.untilHungryMillis(now);
				row(g, "Feed in", PuppyFormat.duration(untilPause),
					untilHungry == null ? WARN : VALUE, left, right, y);
			}
		}

		return new Dimension(WIDTH, height);
	}

	/**
	 * The collapsed card: one row carrying the only number worth glancing
	 * at, plus the button to bring the rest back.
	 */
	private Dimension drawMinimised(Graphics2D g, PuppyTracker tracker, long now,
		boolean grown, boolean paused)
	{
		int height = PAD + TITLE_H + PAD - 4;
		int left = PAD;
		int right = MINIMISED_WIDTH - PAD;
		int y = PAD + TITLE_H - 5;

		Color accent = grown ? OK : paused ? STOPPED : tracker.isHungry() ? WARN : OK;

		g.setColor(BACKGROUND);
		g.fill(new RoundRectangle2D.Float(0, 0, MINIMISED_WIDTH, height, CORNER, CORNER));
		g.setColor(accent);
		g.fill(new RoundRectangle2D.Float(0, 0, STRIPE_W + CORNER, height, CORNER, CORNER));
		g.setColor(BACKGROUND);
		g.fillRect(STRIPE_W, 0, CORNER, height);

		g.setFont(VALUE_FONT);
		g.setColor(grown ? OK : paused ? STOPPED : VALUE);
		g.drawString(grown ? "Grown" : PuppyFormat.duration(tracker.untilGrownMillis(now)), left, y);

		drawButton(g, right, y, "+");

		return new Dimension(MINIMISED_WIDTH, height);
	}

	/**
	 * Draws the minimise/restore square and remembers where it went.
	 */
	private void drawButton(Graphics2D g, int right, int baseline, String glyph)
	{
		int x = right - BUTTON;
		int yTop = baseline - BUTTON + 2;

		g.setColor(new Color(255, 255, 255, 30));
		g.fill(new RoundRectangle2D.Float(x, yTop, BUTTON, BUTTON, 4, 4));
		g.setFont(VALUE_FONT);
		g.setColor(LABEL);

		int glyphWidth = g.getFontMetrics().stringWidth(glyph);
		g.drawString(glyph, x + (BUTTON - glyphWidth) / 2, yTop + BUTTON - 3);

		buttonBounds.setBounds(x, yTop, BUTTON, BUTTON);
	}

	private static void row(Graphics2D g, String label, String value, Color valueColour,
		int left, int right, int baseline)
	{
		g.setFont(LABEL_FONT);
		g.setColor(LABEL);
		g.drawString(label, left, baseline);

		g.setFont(VALUE_FONT);
		g.setColor(valueColour);
		g.drawString(value, right - g.getFontMetrics().stringWidth(value), baseline);
	}
}

package com.psgill.puppy;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
