	{
		return Notification.ON;
	}
}

package com.psgill.puppy;

/**
 * Duration formatting for the overlay and panel.
 *
 * Its own class, like the sibling death-cost plugin's formatter, because
 * these are the strings most likely to be argued with — "is 90 seconds shown
 * as 1m or 1m 30s" is a question worth answering in a test rather than in
 * three slightly different places.
 */
final class PuppyFormat
{
	private PuppyFormat()
	{
	}

	/**
	 * Compact countdown: {@code 45s}, {@code 12m 30s}, {@code 1h 05m}.
	 *
	 * Seconds are dropped above an hour because at that range they are
	 * noise, and shown below a minute because at that range they are the
	 * whole message.
	 */
	static String duration(long millis)
	{
		long totalSeconds = Math.max(0, millis / 1000);
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;

		if (hours > 0)
		{
			return String.format("%dh %02dm", hours, minutes);
		}

		if (minutes > 0)
		{
			return String.format("%dm %02ds", minutes, seconds);
		}

		return seconds + "s";
	}

	/**
	 * A timer's remaining time as the overlay wants to read it: a plain
	 * countdown while there is time left, and how late you are once there is
	 * not. Null means no timer is running.
	 */
	static String remaining(Long remainingMillis)
	{
		if (remainingMillis == null)
		{
			return "--";
		}

		if (remainingMillis >= 0)
		{
			return duration(remainingMillis);
		}

		return "-" + duration(-remainingMillis);
	}

	/** Longer form for the panel, where there is room for words. */
	static String remainingLong(Long remainingMillis)
	{
		if (remainingMillis == null)
		{
			return "not tracked yet";
		}

		if (remainingMillis >= 0)
		{
			return "in " + duration(remainingMillis);
		}

		return duration(-remainingMillis) + " overdue";
	}

	/** Seconds as a profile author would write them: {@code 15m}, {@code 1h 30m}. */
	static String period(long seconds)
	{
		long hours = seconds / 3600;
		long minutes = (seconds % 3600) / 60;
		long rest = seconds % 60;

		if (hours > 0)
		{
			return minutes == 0 ? hours + "h" : String.format("%dh %02dm", hours, minutes);
		}

		if (minutes > 0)
		{
			return rest == 0 ? minutes + "m" : String.format("%dm %02ds", minutes, rest);
		}

		return seconds + "s";
	}
}

package com.psgill.puppy;

import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import java.util.Locale;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Tracks a puppy growing into a dog, in the shape of the kitten tracker:
 * an overlay of countdowns, and nothing else.
 *
 * The numbers come from the game. {@code PUPPY_GROWTH_TRACKER} and
 * {@code PUPPY_FED_TIMER} are the server's own counters, exposed by RuneLite
 * in 1.12.39, and reading them replaced everything this plugin used to do to
 * guess at them: watching for the feed click, reading the "Guess age" reply,
 * matching the chat line that announces a grown dog, and saving the clocks
 * between sessions. All of that was inference, and all of it could be wrong
 * in ways the player noticed before the plugin did.
 *
 * Two habits are worth keeping in mind when changing this. The counters are
 * read every tick rather than through {@code VarbitChanged}, which does not
 * fire for a value of zero — a puppy just fed reads zero. And they are a
 * player variable rather than a property of your follower, so nothing is
 * read at all unless a pet is actually out.
 */
@Slf4j
@PluginDescriptor(
	name = "Puppy Tracker",
	description = "Feed and growth timers for a puppy, in the style of the kitten tracker",
	tags = {"puppy", "dog", "pet", "kitten", "growth", "timer", "overlay"}
)
public class PuppyPlugin extends Plugin
{
	/** Whether the overlay is rolled up. Remembered between sessions. */
	private static final String MINIMISED_KEY = "minimised";

	@Inject
	private Client client;

	@Inject
	private PuppyConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	@Inject
	private PuppyOverlay overlay;

	@Inject
	private MouseManager mouseManager;

	/**
	 * Clicks on the minimise button.
	 *
	 * Overlays get no click handling of their own, so this watches every
	 * press and asks the overlay whether it landed on the button. A press
	 * that did is consumed, or minimising the overlay would also send your
	 * character walking to that spot.
	 */
	private final MouseAdapter mouseAdapter = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (overlay.handleClick(event.getPoint()))
			{
				configManager.setConfiguration(PuppyConfig.GROUP, MINIMISED_KEY,
					Boolean.toString(overlay.isMinimised()));
				event.consume();
			}

			return event;
		}
	};

	private final PuppyTracker tracker = new PuppyTracker();

	/** Whether a puppy was at your heel last tick, to catch it growing. */
	private boolean wasPuppy;

	private boolean warnedHungry;
	private boolean warnedVeryHungry;
	private boolean warnedPaused;
	private boolean warnedGrown;

	@Provides
	PuppyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PuppyConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlay.setMinimised(Boolean.parseBoolean(
			configManager.getConfiguration(PuppyConfig.GROUP, MINIMISED_KEY)));

		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseAdapter);
	}

	@Override
	protected void shutDown()
	{
		mouseManager.unregisterMouseListener(mouseAdapter);
		overlayManager.remove(overlay);
	}

	PuppyTracker tracker()
	{
		return tracker;
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameTick(GameTick event)
	{
		long now = System.currentTimeMillis();
		NPC follower = client.getFollower();
		String name = follower == null ? null : follower.getName();
		boolean puppy = isPuppyName(name);

		// Growing is the moment the follower stops being a puppy, not the
		// moment the counter reaches three hours: the counter is reset the
		// instant the dog matures, so a plugin watching only for 180 sees
		// it flick past and then reads the fresh zero as a new puppy. That
		// is what put a three hour card back on screen beside a grown dog.
		if (wasPuppy && !puppy && follower != null && !warnedGrown)
		{
			warnedGrown = true;
			notifier.notify(config.notifyGrown(), "Your puppy has grown into a dog");
		}

		if (puppy)
		{
			warnedGrown = false;
		}

		wasPuppy = puppy;
		tracker.setFollowing(puppy, puppy ? name : null);

		if (!puppy)
		{
			// The counters belong to the player rather than to whatever is
			// at your heel, so left alone they would happily describe a
			// grown dog, or a puppy sitting in the bank, as still growing.
			tracker.clearReading();
			return;
		}

		tracker.update(
			client.getVarbitValue(VarbitID.PUPPY_GROWTH_TRACKER),
			client.getVarbitValue(VarbitID.PUPPY_FED_TIMER),
			now);

		checkNotifications();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			tracker.setFollowing(false, null);
			tracker.clearReading();
			wasPuppy = false;
		}
	}

	// --------------------------------------------------------- notifications

	/**
	 * Fires each warning once per feed cycle.
	 *
	 * Each flag is cleared by its own condition going false rather than by
	 * spotting the feed that cleared it, which is what the old version did.
	 * Feeding drops the fed timer back to zero on its own, so the flags fall
	 * with it and there is no click to miss.
	 */
	private void checkNotifications()
	{
		if (!tracker.isFollowing() || !tracker.hasReading())
		{
			return;
		}

		if (!tracker.isHungry())
		{
			warnedHungry = false;
		}

		if (!tracker.isVeryHungry())
		{
			warnedVeryHungry = false;
		}

		if (!tracker.isGrowthPaused())
		{
			warnedPaused = false;
		}

		if (tracker.isGrowthPaused() && !warnedPaused)
		{
			warnedPaused = true;
			notifier.notify(config.notifyPaused(), "Your puppy has stopped growing - feed it");
		}
		else if (tracker.isVeryHungry() && !warnedVeryHungry)
		{
			warnedVeryHungry = true;
			notifier.notify(config.notifyVeryHungry(), "Your puppy is very hungry");
		}
		else if (tracker.isHungry() && !warnedHungry)
		{
			warnedHungry = true;
			notifier.notify(config.notifyHungry(), "Your puppy is hungry");
		}
	}

	/**
	 * Whether the follower is a puppy rather than a grown dog.
	 *
	 * The game renames them as they mature — a "Pug puppy" becomes a "Pug"
	 * — and that rename is the only signal separating the two, since no
	 * varbit distinguishes them and the growth counter reads zero for both
	 * a new puppy and a dog that has just finished growing.
	 *
	 * Deliberately a suffix test rather than a list of the twelve breeds:
	 * the quest's own rescued puppies are called just "Puppy" before their
	 * breed is known, and Jagex can add breeds without asking me.
	 */
	static boolean isPuppyName(String name)
	{
		return name != null
			&& name.toLowerCase(Locale.ROOT).trim().endsWith("puppy");
	}

	boolean shouldRender()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		if (config.hideWhenAway() && !tracker.isFollowing())
		{
			return false;
		}

		return !(config.hideWhenGrown() && tracker.isFullyGrown());
	}
}
